class Solution {
    int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
    public boolean exist(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;
        boolean[][] used = new boolean[m][n];
        for(int i=0;i<m;i++){
            for(int j=0;j<n;j++){
                if(dfs(board,word,i,j,0,used)){
                    return true;
                } 
            }
        }
        return false;
    }
    private boolean dfs(char[][] board, String word, int i, int j, int valid, boolean[][] used){
        if(valid == word.length()){
            return true;
        }
        if(i<0 || i>=board.length || j<0 || j>=board[0].length 
        || word.charAt(valid) != board[i][j] || used[i][j]) return false;
        used[i][j] = true;
        for(int[] dir : dirs){
            int x = i + dir[0];
            int y = j + dir[1];
            if(dfs(board,word,x,y,valid+1,used)) return true;
        }
        used[i][j] = false;
        return false;
    }
}
